WF.add({
  id: "spo-fussball", cat: "sport", min: 6, wiki: "Fußball", tags: ["Fußball", "WM", "Bundesliga", "DFB", "Regeln"],
  title: "Fußball: Wie das Spiel die Welt eroberte",
  hook: "Vom chaotischen Dorfgerangel zum Milliardengeschäft: Wie Fußball entstand und warum Frauen ihn in Deutschland 15 Jahre lang nicht spielen durften.",
  cards: [
    { h: "Alte Wurzeln, englische Regeln", t: "Ballspiele mit dem Fuß gab es schon in der Antike. Im alten China spielte man **Cuju**, bei dem ein Lederball in ein Netz befördert werden musste. Die FIFA erkennt es als frühe Form des Fußballs an. Im mittelalterlichen England traten ganze Dörfer in wilden Spielen ohne feste Regeln gegeneinander an, oft mit Verletzten.\n\nDer moderne Fußball entstand **1863** in **London**. Vertreter mehrerer Vereine gründeten die **Football Association** und schrieben einheitliche Regeln. Der entscheidende Punkt: Das Spielen mit der **Hand** wurde verboten. Wer das nicht wollte, spielte weiter das Spiel, aus dem **Rugby** wurde. Deshalb heißt Fußball im Englischen auch „soccer“, von association football.", merke: "1863 legte die Football Association in London die Regeln fest. Handspiel wurde verboten." },
    { h: "Fußball kommt nach Deutschland", t: "In Deutschland galt Fußball zunächst als rüpelhafter englischer Import. Turner verspotteten ihn als **„Fußlümmelei“** und „englische Krankheit“. Der Braunschweiger Lehrer **Konrad Koch** brachte das Spiel **1874** an seine Schule, weil er den Teamgeist schätzte. Er übersetzte auch englische Begriffe: Aus „goal“ wurde **Tor**, aus „offside“ **abseits**.\n\n**1900** wurde in Leipzig der **Deutsche Fußball-Bund (DFB)** gegründet. Die **Bundesliga** startete erst **1963**. Der **FC Bayern München** ist mit großem Abstand Rekordmeister.", merke: "Konrad Koch brachte Fußball 1874 an deutsche Schulen. Der DFB entstand 1900, die Bundesliga 1963." },
    { h: "Weltmeisterschaften", t: "Die erste **Weltmeisterschaft** fand **1930** in **Uruguay** statt, und der Gastgeber gewann. Rekordweltmeister ist **Brasilien** mit fünf Titeln.\n\nDeutschland wurde viermal Weltmeister: **1954**, **1974**, **1990** und **2014**. Besonders der erste Titel hatte Bedeutung weit über den Sport hinaus. Beim **„Wunder von Bern“** schlug die Bundesrepublik im Finale die favorisierten Ungarn mit 3:2. Neun Jahre nach Kriegsende gab das vielen Deutschen ein neues Selbstwertgefühl. Die WM 2026 in den **USA, Kanada und Mexiko** war die erste mit **48** statt 32 Mannschaften.", merke: "Deutschland wurde 1954, 1974, 1990 und 2014 Weltmeister. Brasilien ist mit fünf Titeln Rekordweltmeister.",
      check: { q: "Warum war das „Wunder von Bern“ 1954 so bedeutsam?", o: ["Es gab der jungen Bundesrepublik nach dem Krieg ein neues Selbstwertgefühl", "Es war die erste WM überhaupt", "Deutschland gewann gegen Brasilien"], a: 0, e: "Der überraschende Sieg gegen Ungarn wurde zum Gründungsmythos der Nachkriegszeit." } },
    { h: "Verbotener Frauenfußball", t: "Von **1955 bis 1970** verbot der DFB seinen Vereinen, Frauenfußball anzubieten. Die Begründung klingt heute absurd: Der Sport schade der **„weiblichen Anmut“** und Würde, beim Kampf um den Ball verschwinde die weibliche Würde. Frauen spielten trotzdem, in eigenen Ligen und auf geliehenen Plätzen.\n\nNach Aufhebung des Verbots ging es langsam bergauf. Heute gehört die deutsche Frauen-Nationalmannschaft zu den erfolgreichsten der Welt: **zweimal Weltmeister** (2003 und 2007) und **achtmal Europameister**. Frauenfußball wächst weltweit stark, mit Rekordkulissen in vollen Stadien.", merke: "Der DFB verbot Frauenfußball von 1955 bis 1970. Die Frauen wurden später zweimal Weltmeister." },
    { h: "Regeln, Karten und Technik", t: "Fußball hat überraschend wenige Grundregeln. Die berüchtigtste ist **Abseits**: Ein Spieler steht im Abseits, wenn er beim Abspiel näher an der gegnerischen Torlinie ist als der Ball und der vorletzte Gegenspieler und ins Spiel eingreift.\n\nDie **Gelbe** und **Rote Karte** gibt es erst seit der WM **1970**. Erfunden hat sie der englische Schiedsrichter **Ken Aston**, angeblich inspiriert von einer **Ampel**, nachdem es 1966 Verwirrung um mündliche Verwarnungen gegeben hatte. Seit der WM **2018** hilft der **Videoassistent (VAR)** bei strittigen Szenen. Für viele Fans ist er bis heute umstritten, weil Jubel nun oft unter Vorbehalt steht.", merke: "Gelbe und Rote Karte gibt es seit 1970, inspiriert von einer Ampel. Den VAR gibt es bei WMs seit 2018." },
  ],
  quiz: [
    { t: "gap", q: "Die Football Association, die die modernen Regeln schrieb, wurde ___ in London gegründet.", a: ["1863"], e: "Das Verbot des Handspiels trennte Fußball von Rugby." },
    { t: "order", q: "Bring Deutschlands WM-Titel in die richtige Reihenfolge.", o: ["Wunder von Bern", "Titel im eigenen Land", "Titel in Italien", "Titel in Brasilien"], e: "1954 in der Schweiz, 1974 in Deutschland, 1990 in Italien, 2014 in Brasilien." },
    { t: "tf", q: "Der DFB verbot zwischen 1955 und 1970 Frauenfußball in seinen Vereinen.", a: true, e: "Die Begründung: Der Sport schade der weiblichen Würde." },
    { t: "mc", q: "Wovon ließ sich Ken Aston bei der Erfindung der Gelben und Roten Karte inspirieren?", o: ["Von einer Ampel", "Von Spielkarten", "Von Flaggen", "Von Verkehrsschildern"], a: 0, e: "Gelb heißt Achtung, Rot heißt Stopp." },
    { t: "match", q: "Ordne zu.", pairs: [["Konrad Koch", "Brachte Fußball an deutsche Schulen"], ["Cuju", "Altes chinesisches Ballspiel"], ["Brasilien", "Rekordweltmeister"], ["VAR", "Videoassistent seit der WM 2018"]], e: "Geschichte und Gegenwart des Fußballs." },
  ],
  tips: ["Film: „Das Wunder von Bern“ (2003) erzählt den WM-Sieg 1954 aus Sicht einer Familie in der Nachkriegszeit.", "Ausflug: Das Deutsche Fußballmuseum in Dortmund ist auch für Leute spannend, die keine großen Fans sind.", "Erklär einem Freund die Abseitsregel in einem Satz. Klappt es ohne Hände und Zeichnung?"],
  fact: "Bei der WM 1950 trat die indische Mannschaft angeblich nicht an, auch weil die FIFA ihr verbot, **barfuß** zu spielen. Ob das der wahre Grund war, ist unter Historikern umstritten.",
});

WF.add({
  id: "spo-schach", cat: "sport", min: 6, wiki: "Schach", tags: ["Schach", "Kasparow", "Deep Blue", "Strategie", "Spiele"],
  title: "Schach: 1.500 Jahre Strategie",
  hook: "Ein Spiel aus Indien, das Könige, Spione und Computer in seinen Bann zog. Und warum es mehr mögliche Partien gibt als Atome im Universum.",
  cards: [
    { h: "Von Indien in die Welt", t: "Schach entstand vermutlich im **6. Jahrhundert** in **Indien**. Das Spiel hieß **Chaturanga**, was so viel wie „vier Glieder“ bedeutet: Fußsoldaten, Reiter, Elefanten und Streitwagen, die vier Teile eines indischen Heeres.\n\nÜber **Persien** gelangte es in die arabische Welt und von dort um das Jahr 1000 über Spanien und Italien nach Europa. Aus dieser Reise stammt das Wort **Schachmatt**: Es kommt vom persischen **„schah mat“**, was etwa bedeutet: Der König ist hilflos, er ist besiegt. Das Wort **Schach** selbst kommt vom persischen **Schah** für König.", merke: "Schach entstand in Indien als Chaturanga. Schachmatt kommt vom persischen „schah mat“." },
    { h: "Die Dame wird mächtig", t: "Im mittelalterlichen Schach war die Figur neben dem König schwach: ein **Wesir**, ein Berater, der nur ein Feld schräg ziehen durfte. Partien zogen sich deshalb oft endlos hin.\n\nUm **1475**, wohl in **Spanien**, änderten sich die Regeln dramatisch: Aus dem Wesir wurde die **Dame**, die sich nun beliebig weit gerade und schräg bewegen konnte, die stärkste Figur des Spiels. Manche Historiker bringen das mit mächtigen Königinnen wie **Isabella von Kastilien** in Verbindung. Das neue Spiel war viel schneller und angriffslustiger. Diese Regeln gelten im Wesentlichen bis heute.", merke: "Um 1475 wurde die Dame zur stärksten Figur. Vorher war sie ein schwacher Wesir." },
    { h: "Mensch gegen Maschine", t: "Schach galt lange als Inbegriff menschlicher Intelligenz. Dann kam der **11. Mai 1997**: Der IBM-Computer **Deep Blue** besiegte Weltmeister **Garri Kasparow** in einem Wettkampf über sechs Partien. Ein Schock für viele, ein Meilenstein für die KI-Forschung.\n\nDeep Blue rechnete mit roher Gewalt Millionen Stellungen pro Sekunde durch. **2017** zeigte **AlphaZero** von Google DeepMind einen anderen Weg: Das Programm bekam nur die Regeln, spielte gegen sich selbst und war nach wenigen Stunden Training stärker als die besten Schachprogramme. Heute schlägt jede kostenlose Schach-App den Weltmeister. Trotzdem ist Schach unter Menschen beliebter denn je.", merke: "1997 besiegte Deep Blue Weltmeister Kasparow. AlphaZero lernte 2017 Schach durch Spiel gegen sich selbst.",
      check: { q: "Was war das Besondere an AlphaZero?", o: ["Es lernte Schach nur durch Spiele gegen sich selbst", "Es war der erste Schachcomputer überhaupt", "Es verlor gegen Kasparow"], a: 0, e: "AlphaZero bekam keine menschlichen Partien als Vorbild, nur die Regeln." } },
    { h: "Schach im Kalten Krieg", t: "Im 20. Jahrhundert dominierte die **Sowjetunion** das Schach. Der Staat förderte es als Beweis für die Überlegenheit des Systems. Umso größer war die Sensation **1972** in **Reykjavík**: Der exzentrische Amerikaner **Bobby Fischer** forderte Weltmeister **Boris Spasski** heraus und gewann. Das „Match des Jahrhunderts“ wurde weltweit verfolgt wie ein Stellvertreterkampf der Supermächte.\n\nHeute ist der Norweger **Magnus Carlsen** der bekannteste Spieler. Er erreichte 2014 mit **2882** die höchste Elo-Wertung der Geschichte. Die **Elo-Zahl**, benannt nach dem Physiker **Arpad Elo**, misst die Spielstärke und wird inzwischen auch in Videospielen und Online-Ranglisten verwendet.", merke: "Bobby Fischer besiegte 1972 Boris Spasski. Magnus Carlsen hält den Elo-Rekord von 2882." },
    { h: "Unendliche Möglichkeiten", t: "Schach hat nur 64 Felder und 32 Figuren, und doch ist es praktisch unerschöpflich. Der Mathematiker **Claude Shannon** schätzte 1950 die Zahl der möglichen Partien auf etwa **10 hoch 120**. Zum Vergleich: Die Zahl der Atome im beobachtbaren Universum liegt bei etwa 10 hoch 80. Schon nach wenigen Zügen entstehen Stellungen, die vermutlich noch nie gespielt wurden.\n\nDie Netflix-Serie **„Das Damengambit“** löste 2020 zusammen mit der Pandemie einen weltweiten **Schach-Boom** aus. Plattformen wie Chess.com und Lichess haben heute zig Millionen Nutzer. Studien zeigen, dass Schach Konzentration und Planungsdenken trainiert, ob es allgemein intelligenter macht, ist allerdings umstritten.", merke: "Es gibt etwa 10 hoch 120 mögliche Schachpartien, mehr als Atome im Universum." },
  ],
  quiz: [
    { t: "mc", q: "Was bedeutet „Schachmatt“ ursprünglich?", o: ["Das Spiel ist unentschieden", "Der König ist hilflos, besiegt", "Die Dame ist gefangen", "Der Bauer hat gewonnen"], a: 1, e: "Vom persischen „schah mat“." },
    { t: "gap", q: "Der IBM-Computer, der 1997 Garri Kasparow besiegte, hieß Deep ___.", a: ["Blue"], e: "Ein Meilenstein der KI-Geschichte." },
    { t: "tf", q: "Die Dame war schon immer die stärkste Figur im Schach.", a: false, e: "Bis etwa 1475 war sie ein schwacher Wesir, der nur ein Feld schräg ziehen durfte." },
    { t: "order", q: "Bring die Ereignisse in die richtige Reihenfolge.", o: ["Chaturanga in Indien", "Die Dame wird zur stärksten Figur", "Fischer gegen Spasski", "Deep Blue besiegt Kasparow", "AlphaZero lernt Schach selbst"], e: "6. Jh., um 1475, 1972, 1997, 2017." },
    { t: "match", q: "Ordne zu.", pairs: [["Magnus Carlsen", "Elo-Rekord 2882"], ["Bobby Fischer", "Sieg in Reykjavík 1972"], ["Claude Shannon", "Schätzte die Zahl möglicher Partien"], ["Arpad Elo", "Erfand die Wertungszahl"]], e: "Große Namen der Schachgeschichte." },
  ],
  tips: ["Lerne die Grundregeln auf Lichess.org. Die Plattform ist kostenlos, werbefrei und hat interaktive Lektionen.", "Serie: „Das Damengambit“ (Netflix) ist spannend, auch wenn man kaum Schach spielt.", "Probier täglich ein Schachrätsel aus. Es trainiert vorausschauendes Denken in fünf Minuten."],
  fact: "Das längste theoretisch mögliche Schachspiel hätte wegen der **50-Züge-Regel** rund **6.000 Züge**. Die längste offizielle Turnierpartie dauerte 269 Züge.",
});

